package ktanesolver.module.modded.regular.vexillology;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class VexillologySolverTest{@Test void solvesSimpleHorizontalFlag(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");@SuppressWarnings("unchecked")VexillologyOutput o=((SolveSuccess<VexillologyOutput>)new VexillologySolver().solve(new RoundEntity(),b,new ModuleEntity(),new VexillologyInput("horizontal",List.of("red","blue","green")))).output();assertThat(o.flagColors()).hasSize(3);assertThat(o.commands()).last().isEqualTo("submit on 3");}}
